package dev.astralreach.hytale;
import com.hypixel.hytale.component.*;import com.hypixel.hytale.protocol.*;import com.hypixel.hytale.protocol.packets.entities.EntityUpdates;import com.hypixel.hytale.server.core.asset.type.model.config.*;import com.hypixel.hytale.server.core.entity.entities.Player;import com.hypixel.hytale.server.core.modules.entity.component.TransformComponent;import com.hypixel.hytale.server.core.universe.*;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;import org.joml.Vector3d;import java.util.*;import java.util.concurrent.*;
/** Bounded observer-local distant plume projections from actual server flight phases. */
final class FlightSightings{
 record Sighting(UUID pilot,Vector3d position,boolean returning){}
 private record Seen(int networkId){}
 private static final class View{final Store<EntityStore>store;final PlayerRef player;final Object connection;final Map<UUID,Seen>seen=new HashMap<>();long sent;View(Store<EntityStore>s,PlayerRef p){store=s;player=p;connection=p.getPacketHandler();}}
 private static final Map<UUID,View>views=new ConcurrentHashMap<>();private static com.hypixel.hytale.protocol.Model ascent,reentry;
 static void tick(Store<EntityStore>s,List<Sighting>flights){var w=s.getExternalData().getWorld();if(!StationFlyovers.surface(w))return;for(var p:w.getPlayerRefs()){var r=p.getReference();if(r==null||!r.isValid()||r.getStore()!=s)continue;var view=views.get(p.getUuid());if(view!=null&&(view.store!=s||view.player!=p||view.connection!=p.getPacketHandler())){views.remove(p.getUuid(),view);view=null;}if(view==null){view=new View(s,p);views.put(p.getUuid(),view);}if(System.nanoTime()-view.sent<100_000_000L)continue;view.sent=System.nanoTime();var at=s.getComponent(r,TransformComponent.getComponentType()).getPosition();var updates=new ArrayList<EntityUpdate>();var removed=new ArrayList<Integer>();var wanted=new HashSet<UUID>();var f=s.getComponent(r,AstralReachPlugin.flightType);if(f==null||!f.boarded)for(var flight:flights){double distance=at.distance(flight.position());if(p.getUuid().equals(flight.pilot())||distance<256||distance>12000||flight.position().y<at.y+20)continue;wanted.add(flight.pilot());var seen=view.seen.get(flight.pilot());boolean fresh=seen==null;if(fresh){seen=new Seen(s.getExternalData().takeNextNetworkId());view.seen.put(flight.pilot(),seen);}var direction=new Vector3d(flight.position()).sub(at).normalize();var pos=new Vector3d(at).add(0,1.6,0).add(direction.mul(96));var angle=com.hypixel.hytale.math.vector.Rotation3f.lookAt(new Vector3d(at).sub(pos));var rot=new Direction(angle.yaw(),angle.pitch(),flight.returning()?(float)Math.toRadians(30):0);var parts=new ArrayList<ComponentUpdate>();if(fresh){parts.add(new NewSpawnUpdate());parts.add(new PropUpdate());parts.add(new IntangibleUpdate());}parts.add(new ModelUpdate(model(flight.returning()),1));parts.add(new TransformUpdate(new ModelTransform(new Position(pos.x,pos.y,pos.z),rot,rot)));updates.add(new EntityUpdate(seen.networkId(),null,parts.toArray(ComponentUpdate[]::new)));if(wanted.size()>=3)break;}
 for(var e:new ArrayList<>(view.seen.entrySet()))if(!wanted.contains(e.getKey())){removed.add(e.getValue().networkId());view.seen.remove(e.getKey());}if(!updates.isEmpty()||!removed.isEmpty())p.getPacketHandler().writeNoCache(new EntityUpdates(removed.stream().mapToInt(Integer::intValue).toArray(),updates.toArray(EntityUpdate[]::new)));}
 for(var e:new ArrayList<>(views.entrySet())){var v=e.getValue();var r=v.player.getReference();if(v.store==s&&(r==null||!r.isValid()||r.getStore()!=s||Universe.get().getPlayer(v.player.getUuid())!=v.player))views.remove(e.getKey(),v);}}
 private static synchronized com.hypixel.hytale.protocol.Model model(boolean back){if(back){if(reentry==null)reentry=com.hypixel.hytale.server.core.asset.type.model.config.Model.createScaledModel(ModelAsset.getAssetMap().getAsset("AR_ReentryDistant"),1).toPacket();return reentry;}if(ascent==null)ascent=com.hypixel.hytale.server.core.asset.type.model.config.Model.createScaledModel(ModelAsset.getAssetMap().getAsset("AR_LaunchDistant"),1).toPacket();return ascent;}
 private FlightSightings(){}
}
